    function answerValid(q,a){if(q.bentuk==='PG')return Number.isInteger(a)&&a>=0&&a<q.options.length;if(q.bentuk==='PGK')return Array.isArray(a)&&a.length>0&&a.every(x=>Number.isInteger(x)&&x>=0&&x<q.options.length)&&new Set(a).size===a.length;return Array.isArray(a)&&a.length===q.options.length&&a.every(x=>x==='B'||x==='S');}
